// ===== v0: png.c before #3339 =====
// Dependency-free PNG decoder. v0_image_png_process validates the complete PNG
// chunk stream first, including every CRC and the ordering constraints needed
// by the decoder. Probe mode stops after publishing bounded metadata. Decode
// mode then consumes the concatenated IDAT payload as one zlib stream, expands
// stored/fixed/dynamic DEFLATE blocks into the exact expected scanline image,
// validates Adler-32, reverses filters in place, and scatters ordinary or
// Adam7 samples into the public top-left RGBA8 output.
//
// Layout map (searchable symbols, not line numbers):
//   v0_PngState, v0_png_parse_*               chunk grammar, color and APNG metadata
//   v0_PngCompressedInput                  split-IDAT byte stream
//   v0_PngBitReader, v0_PngHuffman            bounded DEFLATE machinery
//   v0_png_inflate_zlib                    zlib header/body/Adler-32
//   v0_png_filtered_size                   exact scanline allocation census
//   v0_png_unfilter_row, v0_png_expand_pixels filters, samples and Adam7 scatter
//   v0_image_png_process                   public codec seam


#define v0_PNG_SIGNATURE_SIZE 8u
#define v0_PNG_CHUNK_HEADER_SIZE 8u
#define v0_PNG_CHUNK_CRC_SIZE 4u
#define v0_PNG_U31_MAX UINT32_C(0x7fffffff)
#define v0_PNG_CHUNK_MAX_LENGTH v0_PNG_U31_MAX
#define v0_PNG_DEFLATE_MAX_BITS 15u
#define v0_PNG_DEFLATE_LITERAL_SYMBOL_COUNT 288u
#define v0_PNG_DEFLATE_DISTANCE_SYMBOL_COUNT 32u
#define v0_PNG_DEFLATE_CODE_LENGTH_SYMBOL_COUNT 19u
#define v0_PNG_DEFLATE_DYNAMIC_LENGTH_COUNT 320u
#define v0_PNG_ADLER_MODULUS 65521u

#define v0_PNG_CHUNK_TYPE(a, b, c, d)                                                                                                                            \
    (((u32)(u8)(a) << 24u) | ((u32)(u8)(b) << 16u) | ((u32)(u8)(c) << 8u) | (u32)(u8)(d))

